/**
 * Verification & AI Audit Trail Notes Utilities
 * Unifies AI diagnostic note parsing, triage indicators, and tier resolution across
 * the HALALVERIFY Verification Queue.
 */

/**
 * Checks whether an admin_notes entry was generated by the backend automated verification engine
 * or system invariants rather than entered by a human administrator.
 */
export function isMachineNote(rawNote) {
    if (!rawNote || typeof rawNote !== 'string') return false;
    const text = rawNote.trim();
    return (
        text.startsWith('FATAL INVARIANT') ||
        text.startsWith('AI ') ||
        text.startsWith('[AI ') ||
        text.startsWith('Classification Tier:')
    );
}

/**
 * Parses automated AI evaluation strings emitted by auto_verification_service.py.
 * Returns structured metadata for badges, audit trails, and review notices.
 *
 * @param {string} rawNote - The stored admin_notes or evaluation summary note.
 * @returns {{
 *   kind: 'blocked' | 'needs_review' | 'auto_published' | null,
 *   score: number | null,
 *   reasons: string[],
 *   raw: string
 * } | null}
 */
export function parseAiTriage(rawNote) {
    if (!rawNote || typeof rawNote !== 'string') {
        return null;
    }
    const text = rawNote.trim();
    if (!isMachineNote(text)) {
        return null;
    }

    let kind = null;
    const textLower = text.toLowerCase();

    if (textLower.includes('fatal invariant') || textLower.includes('blocked from auto-approval')) {
        kind = 'blocked';
    } else if (
        textLower.includes('ai verified & published') ||
        textLower.includes('ai triaged & published') ||
        textLower.includes('ai auto-approved')
    ) {
        kind = 'auto_published';
    } else if (textLower.includes('ai audited')) {
        kind = 'needs_review';
    }

    // Extract confidence score (e.g. "Confidence: 85%" or "scored 72%")
    let score = null;
    const scoreMatch = text.match(/(?:confidence:\s*|scored\s*)(\d+)%/i);
    if (scoreMatch) {
        score = parseInt(scoreMatch[1], 10);
    }

    // Extract reasons/issues
    const reasons = [];
    if (/issues:\s*/i.test(text)) {
        const issuesPart = text.split(/issues:\s*/i)[1]?.split('|')[0] || '';
        const rawIssues = issuesPart.replace(/\.?\s*Queued for final.*$/i, '').trim();
        const splitIssues = rawIssues
            .split(';')
            .map((s) => s.trim().replace(/\.$/, ''))
            .filter(Boolean);
        reasons.push(...splitIssues);
    } else if (kind === 'blocked') {
        const cleaned = text
            .replace(/^FATAL INVARIANT FAILED:\s*/i, '')
            .replace(/\(Confidence:\s*\d+%\)\.?\s*/i, '')
            .split('|')[0]
            .trim();
        if (cleaned) {
            reasons.push(cleaned);
        }
    }

    return {
        kind,
        score,
        reasons,
        raw: text,
    };
}

/**
 * Extracts a concise system explanation for why manual inspection was triggered.
 */
export function formatSystemNotice(rawNote) {
    const triage = parseAiTriage(rawNote);
    if (!triage) return null;

    if (triage.reasons && triage.reasons.length > 0) {
        return triage.reasons.join('; ');
    }

    if (triage.kind === 'blocked') {
        return triage.raw
            .replace(/^FATAL INVARIANT FAILED:\s*/i, '')
            .replace(/\(Confidence:\s*\d+%\)\.?\s*/i, '')
            .split('|')[0]
            .trim();
    }

    return null;
}

/**
 * Deterministically resolves an establishment's verification tier in client state
 * (mirrors backend registry.py enrich_establishment_tier / derive_establishment_tier).
 */
export function deriveEstablishmentTier(record) {
    if (!record || typeof record !== 'object') {
        return 'halal_certified';
    }

    const explicit = (record.verification_tier || record.halal_tier || '').trim().toLowerCase();
    if (['halal_certified', 'muslim_owned', 'muslim_friendly', 'vegetarian_vegan'].includes(explicit)) {
        return explicit;
    }

    const combined = `${record.description || ''} ${record.admin_notes || ''} ${record.halal_status || ''}`.toLowerCase();
    if (combined.includes('[tier: muslim_owned]') || combined.includes('muslim-owned') || combined.includes('muslim_owned')) {
        return 'muslim_owned';
    }
    if (combined.includes('[tier: muslim_friendly]') || combined.includes('muslim-friendly') || combined.includes('muslim_friendly')) {
        return 'muslim_friendly';
    }
    if (combined.includes('[tier: vegetarian_vegan]') || combined.includes('vegetarian') || combined.includes('vegan') || combined.includes('plant-based')) {
        return 'vegetarian_vegan';
    }
    if (combined.includes('community listed') && !(record.certifying_body_id || record.certificate_number)) {
        return 'muslim_owned';
    }

    return 'halal_certified';
}

/**
 * Extracts menu highlights / dishes list from an establishment record across all fallback schemas.
 * Checks menu_highlights column, associated_products array, description string, and admin_notes string.
 */
export function extractMenuHighlights(record) {
    if (!record || typeof record !== 'object') return [];
    if (Array.isArray(record.menu_highlights) && record.menu_highlights.length > 0) {
        return record.menu_highlights.filter(Boolean);
    }
    if (Array.isArray(record.associated_products) && record.associated_products.length > 0) {
        return record.associated_products.map((p) => p.name || p).filter(Boolean);
    }
    const combined = `${record.description || ''} \n ${record.admin_notes || ''}`;
    const match = combined.match(/(?:Dishes|Specialties|Menu):\s*([^|\n\]]+)/i);
    if (match && match[1]) {
        return match[1].split(',').map((s) => s.trim()).filter(Boolean);
    }
    return [];
}

/**
 * Formats date strings to clean short date standard (e.g. "Oct 13, 2026").
 */
export function formatShortDate(dateStr) {
    if (!dateStr) return 'Recent';
    try {
        const d = new Date(dateStr);
        if (Number.isNaN(d.getTime())) return 'Recent';
        return d.toLocaleDateString(undefined, {
            month: 'short',
            day: 'numeric',
            year: 'numeric',
        });
    } catch {
        return 'Recent';
    }
}
